logging.basicConfig(level=logging.INFO)
logger = logging.getLogger('jade.polyglot')

class LanguageType(Enum):
    COMPILED = "compiled"
    INTERPRETED = "interpreted"
    SCRIPTED = "scripted"
    MARKUP = "markup"
    QUERY = "query"
    CONFIGURATION = "configuration"
    FUNCTIONAL = "functional"
    ASSEMBLY = "assembly"

@dataclass
class LanguageDefinition:
    name: str
    extensions: List[str]
    language_type: LanguageType
    syntax_patterns: Dict[str, List[str]]
    security_patterns: Dict[str, List[str]]
    compiler_command: Optional[str] = None
    interpreter_command: Optional[str] = None

@dataclass
class PolyglotAnalysisResult:
    language: str
    confidence: float
    security_issues: List[Dict[str, Any]]
    code_quality_score: float
    complexity_metrics: Dict[str, Any]
    vulnerability_count: int
    performance_metrics: Dict[str, Any]
    recommendations: List[str]

