    def _load_security_rules(self) -> Dict[str, Dict[str, Any]]:
        """Load comprehensive security rules for all languages"""
        return {
            'injection_attacks': {
                'patterns': [r'eval\s*\(', r'exec\s*\(', r'system\s*\('],
                'severity': 'critical',
                'description': 'Code injection vulnerability'
            },
            'buffer_overflows': {
                'patterns': [r'gets\s*\(', r'strcpy\s*\(', r'sprintf\s*\('],
                'severity': 'critical',
                'description': 'Buffer overflow vulnerability'
            },
            'xss_vulnerabilities': {
                'patterns': [r'innerHTML\s*=', r'document\.write\s*\('],
                'severity': 'high',
                'description': 'Cross-site scripting vulnerability'
            },
            'sql_injection': {
                'patterns': [r'SELECT.*\+', r'INSERT.*\+', r'UPDATE.*\+'],
                'severity': 'critical',
                'description': 'SQL injection vulnerability'
            },
            'path_traversal': {
                'patterns': [r'\.\./'],
                'severity': 'high',
                'description': 'Path traversal vulnerability'
            }
        }

    def detect_language(self, code: str, filename: Optional[str] = None) -> Tuple[str, float]:
        """Detect programming language with confidence score"""
        if filename:
            # Check file extension first
            for lang_name, lang_def in self.supported_languages.items():
                for ext in lang_def.extensions:
                    if filename.endswith(ext):
                        return lang_name, 0.9

        # Pattern-based detection
        language_scores = {}

        for lang_name, lang_def in self.supported_languages.items():
            score = 0
            pattern_matches = 0

            for pattern_type, patterns in lang_def.syntax_patterns.items():
                for pattern in patterns:
                    matches = len(re.findall(pattern, code, re.MULTILINE | re.IGNORECASE))
                    if matches > 0:
                        pattern_matches += matches
                        score += matches * 10

            # Normalize score
            if pattern_matches > 0:
                language_scores[lang_name] = min(score / len(code.split('\n')), 1.0)

        if language_scores:
            best_lang = max(language_scores, key=language_scores.get)
            return best_lang, language_scores[best_lang]

        return 'unknown', 0.0

    def analyze_security(self, code: str, language: str) -> PolyglotAnalysisResult:
        """Perform comprehensive security analysis"""
        start_time = time.time()

        security_issues = []
        vulnerability_count = 0

        # Language-specific security patterns
        if language in self.supported_languages:
            lang_def = self.supported_languages[language]

            for vuln_type, patterns in lang_def.security_patterns.items():
                for pattern in patterns:
                    matches = list(re.finditer(pattern, code, re.MULTILINE | re.IGNORECASE))
                    for match in matches:
                        security_issues.append({
                            'type': vuln_type,
                            'severity': 'high',
                            'line': code[:match.start()].count('\n') + 1,
                            'pattern': pattern,
                            'match': match.group(),
                            'description': f'{vuln_type.replace("_", " ").title()} vulnerability detected'
                        })
                        vulnerability_count += 1

        # General security rules
        for rule_name, rule_data in self.security_rules.items():
            for pattern in rule_data['patterns']:
                matches = list(re.finditer(pattern, code, re.MULTILINE | re.IGNORECASE))
                for match in matches:
                    security_issues.append({
                        'type': rule_name,
                        'severity': rule_data['severity'],
                        'line': code[:match.start()].count('\n') + 1,
                        'pattern': pattern,
                        'match': match.group(),
                        'description': rule_data['description']
                    })
                    vulnerability_count += 1

        # Code quality metrics
        complexity_metrics = self._calculate_complexity(code, language)
        code_quality_score = self._calculate_quality_score(code, security_issues, complexity_metrics)

        # Performance metrics
        processing_time = int((time.time() - start_time) * 1000)
        performance_metrics = {
            'processing_time_ms': processing_time,
            'lines_analyzed': len(code.split('\n')),
            'patterns_checked': sum(len(patterns) for patterns in self.security_rules.values())
        }

        # Recommendations
        recommendations = self._generate_recommendations(security_issues, language)

        return PolyglotAnalysisResult(
            language=language,
            confidence=0.95,
            security_issues=security_issues,
            code_quality_score=code_quality_score,
            complexity_metrics=complexity_metrics,
            vulnerability_count=vulnerability_count,
            performance_metrics=performance_metrics,
            recommendations=recommendations
        )

    def _calculate_complexity(self, code: str, language: str) -> Dict[str, Any]:
        """Calculate code complexity metrics"""
        lines = code.split('\n')

        metrics = {
            'total_lines': len(lines),
            'code_lines': len([line for line in lines if line.strip() and not line.strip().startswith('#')]),
            'comment_lines': len([line for line in lines if line.strip().startswith('#')]),
            'cyclomatic_complexity': 1,  # Base complexity
            'nesting_depth': 0,
            'function_count': 0
        }

        # Calculate cyclomatic complexity
        complexity_patterns = [r'\bif\b', r'\bwhile\b', r'\bfor\b', r'\bcase\b', r'\bcatch\b']
        for pattern in complexity_patterns:
            metrics['cyclomatic_complexity'] += len(re.findall(pattern, code, re.IGNORECASE))

        # Calculate nesting depth
        max_depth = 0
        current_depth = 0
        for line in lines:
            if '{' in line:
                current_depth += line.count('{')
            if '}' in line:
                current_depth -= line.count('}')
            max_depth = max(max_depth, current_depth)

        metrics['nesting_depth'] = max_depth

        # Count functions (language-specific)
        if language in self.supported_languages:
            lang_def = self.supported_languages[language]
            if 'function_def' in lang_def.syntax_patterns:
                for pattern in lang_def.syntax_patterns['function_def']:
                    metrics['function_count'] += len(re.findall(pattern, code, re.MULTILINE))

        return metrics

    def _calculate_quality_score(self, code: str, security_issues: List[Dict], complexity_metrics: Dict) -> float:
        """Calculate overall code quality score"""
        base_score = 100.0

        # Deduct for security issues
        for issue in security_issues:
            if issue['severity'] == 'critical':
                base_score -= 20
            elif issue['severity'] == 'high':
                base_score -= 10
            elif issue['severity'] == 'medium':
                base_score -= 5
            else:
                base_score -= 2

        # Deduct for high complexity
        if complexity_metrics['cyclomatic_complexity'] > 20:
            base_score -= 15
        elif complexity_metrics['cyclomatic_complexity'] > 10:
            base_score -= 5

        if complexity_metrics['nesting_depth'] > 6:
            base_score -= 10
        elif complexity_metrics['nesting_depth'] > 4:
            base_score -= 5

        # Bonus for comments
        comment_ratio = complexity_metrics['comment_lines'] / max(complexity_metrics['total_lines'], 1)
        if comment_ratio > 0.2:
            base_score += 5

        return max(0.0, min(100.0, base_score))

    def _generate_recommendations(self, security_issues: List[Dict], language: str) -> List[str]:
        """Generate security recommendations"""
        recommendations = []

        issue_types = set(issue['type'] for issue in security_issues)

        if 'sql_injection' in issue_types:
            recommendations.append("Use parameterized queries to prevent SQL injection")

        if 'xss' in issue_types or 'xss_vulnerabilities' in issue_types:
            recommendations.append("Implement proper output encoding and CSP headers")

        if 'buffer_overflow' in issue_types or 'buffer_overflows' in issue_types:
            recommendations.append("Use safe string functions and bounds checking")

        if 'code_injection' in issue_types or 'injection_attacks' in issue_types:
            recommendations.append("Avoid dynamic code execution and validate all inputs")

        if 'path_traversal' in issue_types:
            recommendations.append("Sanitize file paths and use whitelist validation")

        # Language-specific recommendations
        if language == 'c' or language == 'cpp':
            recommendations.append("Consider using modern C++ RAII and smart pointers")
        elif language == 'javascript':
            recommendations.append("Use strict mode and implement Content Security Policy")
        elif language == 'python':
            recommendations.append("Use type hints and static analysis tools")

        return recommendations

# Demo and integration
class PolyglotSecurityOrchestrator:
    """Main orchestrator for polyglot security analysis"""

    def __init__(self):
        self.polyglot_engine = PolyglotSecurityEngine()
        self.analysis_count = 0

    def analyze_code(self, code: str, filename: Optional[str] = None) -> Dict[str, Any]:
        """Comprehensive polyglot code analysis"""
        start_time = time.time()

        # Detect language
        detected_language, confidence = self.polyglot_engine.detect_language(code, filename)

        # Perform security analysis
        security_result = self.polyglot_engine.analyze_security(code, detected_language)

        self.analysis_count += 1
        total_time = int((time.time() - start_time) * 1000)

        return {
            'analysis_id': hashlib.sha256(f"{code}{time.time()}".encode()).hexdigest()[:16],
            'language_detection': {
                'detected_language': detected_language,
                'confidence': confidence,
                'supported_languages': len(self.polyglot_engine.supported_languages)
            },
            'security_analysis': {
                'vulnerability_count': security_result.vulnerability_count,
                'code_quality_score': security_result.code_quality_score,
                'security_issues': security_result.security_issues[:10],  # Limit for display
                'recommendations': security_result.recommendations
            },
            'complexity_metrics': security_result.complexity_metrics,
            'performance': {
                'total_time_ms': total_time,
                'lines_analyzed': security_result.complexity_metrics['total_lines'],
                'polyglot_engine_ready': True
            },
            'platform_info': {
                'languages_supported': list(self.polyglot_engine.supported_languages.keys()),
                'total_language_count': len(self.polyglot_engine.supported_languages),
                'analysis_count': self.analysis_count
            },
            'timestamp': datetime.now().isoformat()
        }

